/* 通知条：上游 notice 风格 */
.sessmgr-notice { margin: 4px 4px 0; padding: 8px 11px; border-radius: 8px; font-size: 12px; line-height: 18px; color: var(--dsw-alias-label-tertiary, #6b7280); word-break: break-all; }
