    slots.inject('sidebar.footer.action', () => slots.register(
      { name: 'sidebar.footer.action', id: 'plasmid-panel', order: 6, label: () => copy(isZhNow()).badge },
      (props) => h(PlasmidEntry, props),
    ))
  },
